 <?php $__env->startSection('title','Dashboard pemilik'); ?>
<?php $__env->startSection('content'); ?><div class="page"><div class="eyebrow">DASHBOARD / PEMILIK RESTO</div><div class="d-flex justify-content-between align-items-center mb-4"><div><h1>Ruang pemilik</h1><p class="subtitle mb-0">Ringkasan resto dan reservasi yang perlu ditindaklanjuti.</p></div><span class="status" style="background:var(--lav2);color:var(--purple-dark)">Workspace pemilik</span></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="panel"><p class="subtitle mb-1">Jumlah resto</p><h2><?php echo e(isset($restos)?$restos->count():0); ?></h2></div></div><div class="col-md-4"><div class="panel"><p class="subtitle mb-1">Jumlah menu</p><h2><?php echo e(isset($restos)?$restos->sum('menus_count'):0); ?></h2></div></div><div class="col-md-4"><div class="panel"><p class="subtitle mb-1">Reservasi menunggu</p><h2><?php echo e(isset($reservasis)?$reservasis->where('status','menunggu')->count():0); ?></h2></div></div></div><div class="d-flex justify-content-end mb-3"><a href="<?php echo e(route('owner.restos')); ?>" class="btn btn-purple"><i class="bi bi-shop me-2"></i>Kelola resto & menu</a></div><div class="panel"><h5 class="mb-3">Reservasi masuk</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pelanggan</th><th>Resto</th><th>Jadwal</th><th>Tamu</th><th>Total / DP</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php $__empty_1 = true; $__currentLoopData = $reservasis; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $r): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><tr><td><?php echo e($r->user->name??'Pelanggan'); ?></td><td><?php echo e($r->resto->nama??'-'); ?></td><td><?php echo e($r->tanggal->format('d M Y')); ?><br><small class="subtitle"><?php echo e(substr($r->jam,0,5)); ?></small></td><td><?php echo e($r->jumlah_orang); ?></td><td>Rp<?php echo e(number_format($r->total_harga,0,',','.')); ?><br><small class="subtitle">DP Rp<?php echo e(number_format($r->dp_nominal,0,',','.')); ?></small></td><td><span class="status status-<?php echo e($r->status); ?>"><?php echo e(str_replace('_',' ',$r->status)); ?></span></td><td><?php if(auth()->user()->role==='pemilik' && in_array($r->status,['menunggu','dikonfirmasi','check_in'])): ?><form method="POST" action="<?php echo e(route('owner.reservasi.status',$r)); ?>" class="d-flex flex-column gap-1"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><select class="form-select form-select-sm" name="status"><option value="dikonfirmasi">Konfirmasi</option><option value="tolak">Tolak</option><option value="check_in">Check-in</option><option value="lunas">Tandai lunas</option><option value="selesai">Selesai</option></select><input class="form-control form-control-sm" name="alasan_penolakan" placeholder="Alasan jika ditolak"><button class="btn btn-purple btn-sm">Simpan status</button></form><?php if($r->bukti_dp): ?><a class="small d-block mt-2" href="<?php echo e(asset('storage/'.$r->bukti_dp)); ?>" target="_blank" rel="noopener">Lihat bukti DP</a><form method="POST" action="<?php echo e(route('owner.reservasi.dp',$r)); ?>" class="mt-1"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><select class="form-select form-select-sm mb-1" name="status_dp"><option value="diterima">Terima DP</option><option value="ditolak">Tolak DP</option></select><input class="form-control form-control-sm mb-1" name="catatan_dp" placeholder="Catatan jika ditolak"><button class="btn btn-outline-purple btn-sm">Verifikasi DP</button></form><?php endif; ?> <?php else: ?><span class="subtitle small">Lihat detail</span><?php endif; ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><tr><td colspan="7" class="text-center subtitle py-4">Belum ada reservasi masuk.</td></tr><?php endif; ?></tbody></table></div></div></div><?php $__env->stopSection(); ?>

